# ------------------------------------------------------------------------------------------------ 09.11. Große Mauer
TOPICS["20261109-1"] = {
    "series": "Prüfstand", "hook_type": "question", "chapters": CH["pruefstand"], "chmap": [0, 1, 2, 3, 5],
    "focus": ["wall"],
    "cam": {"target": [], "box": [[-160, 150, -40], [160, 200, 40]], "fit0": 0.9, "fit1": 1.0, "el0": 22, "el1": 18},
    "beats": [
        {"scene": "gb_task", "src": ["S2"], "cam": {"az0": 28, "az1": 18},
         "de": {"spoken": "Die Chinesische Mauer soll man aus dem All sehen können. Stimmt das? Die NASA hat dazu eine klare Antwort.",
                "data": {"kicker": "Prüfstand · Chinesische Mauer", "question": "Sieht man die Mauer aus dem All?", "question_at": 0.05,
                         "tag": {"text": "Behauptung: aus dem All sichtbar", "at": "@Stimmt", "y": 1010}}},
         "en": {"spoken": "People say you can see the Great Wall of China from space. Is that true? NASA has a clear answer.",
                "data": {"kicker": "Check · Great Wall of China", "question": "Can you see the Wall from space?", "question_at": 0.05,
                         "tag": {"text": "Claim: visible from space", "at": "@true", "y": 1010}}}},
        {"scene": "gb_principle", "src": ["S1", "S2"], "cam": {"box": [[-1200, 150, -300], [1200, 200, 300]], "el0": 40, "el1": 55, "fit0": 0.8, "fit1": 0.9}, "props": {"ridge2.fade": [[0, 1], ["%0.5", 1], ["%0.7", 0.4]]},
         "de": {"spoken": "Oft heißt es sogar, sie sei das einzige Bauwerk, das man aus dem All sieht. Die NASA nennt das einen Mythos. Vom Mond aus ist sie nicht zu sehen, aus der Erdumlaufbahn mit bloßem Auge schwer bis gar nicht.",
                "data": {"headline": "Der Befund", "note": "laut NASA",
                         "rule": {"text": "Mond: nein. Umlaufbahn: bloßes Auge kaum.", "at": "@Mond", "dy": 640}}},
         "en": {"spoken": "It is often called the only structure you can see from space. NASA calls that a myth. From the Moon it is not visible, and from orbit it is hard or impossible to see with the naked eye.",
                "data": {"headline": "The finding", "note": "according to NASA",
                         "rule": {"text": "Moon: no. Orbit: barely, naked eye.", "at": "@Moon", "dy": 640}}}},
        {"scene": "gb_load", "src": ["S3"], "cam": {"az0": 60, "az1": 75, "el0": 14, "el1": 10},
         "de": {"spoken": "Der Grund ist nicht nur die Entfernung. Entscheidend ist der Kontrast, schreibt die NASA. Die Mauer hebt sich kaum von Vegetation und Boden ab. Satellitensensoren erkennen sie deshalb leichter als das menschliche Auge.",
                "data": {"headline": "Der Grund", "load": {"label": "Entscheidend", "value": "Kontrast", "unit": "", "sub": "nicht nur die Entfernung", "at": "@Kontrast", "dy": 540},
                         "goal": {"key": "BILD", "text": "Mauer hebt sich kaum ab", "at": "@Vegetation", "dy": 420},
                         "pins": [{"anchor": "wall", "text": "Mauer", "at": "@Mauer", "side": "up"}]}},
         "en": {"spoken": "Distance is not the only reason. What matters is contrast, NASA writes. The wall barely stands out from the plants and soil around it. That is why satellite sensors pick it out more easily than the human eye.",
                "data": {"headline": "The reason", "load": {"label": "What matters", "value": "Contrast", "unit": "", "sub": "not just the distance", "at": "@contrast", "dy": 540},
                         "goal": {"key": "IMAGE", "text": "The wall barely stands out", "at": "@plants", "dy": 420},
                         "pins": [{"anchor": "wall", "text": "Wall", "at": "@wall", "side": "up"}]}}},
        {"scene": "gb_proof", "src": ["S1", "S2"], "cam": {"az0": 20, "az1": 5, "el0": 30, "el1": 45, "fit0": 0.95, "fit1": 0.7},
         "de": {"spoken": "Mit Teleobjektiv sieht es anders aus. Leroy Chiao, Kommandant der Expedition 10, hat die Mauer von der Raumstation aus fotografiert. Auch auf manchen hochauflösenden Astronautenfotos ist sie zu erkennen. Das Foto entstand also mit langer Brennweite, nicht mit bloßem Auge.",
                "data": {"headline": "Die Gegenprobe", "stamp": {"date": "EXPEDITION 10", "event": "Foto von der ISS", "at": "@Expedition", "dy": 150},
                         "pins": [{"anchor": "far", "text": "Teleobjektiv: ja", "at": "@fotografiert", "side": "up"}]}},
         "en": {"spoken": "With a telephoto lens it is a different story. Leroy Chiao, commander of Expedition 10, photographed the wall from the space station. It can also be made out on some high-resolution astronaut photos. So the picture was taken with a long lens, not with the naked eye.",
                "data": {"headline": "The check", "stamp": {"date": "EXPEDITION 10", "event": "Photo from the ISS", "at": "@Expedition", "dy": 150},
                         "pins": [{"anchor": "far", "text": "Telephoto: yes", "at": "@photographed", "side": "up"}]}}},
        {"scene": "gb_close", "src": ["S2"], "cam": {"az0": 35, "az1": 25, "el0": 25, "el1": 20},
         "de": {"spoken": "Also: fotografierbar ja, mit bloßem Auge nein. Chinas erster Astronaut Yang Liwei sagte, er habe die Mauer nicht gesehen. Unsichtbar ist sie im All also nicht, aber man sieht sie eben auch nicht einfach so. Folge Gigastruct für den nächsten Prüfstand.",
                "data": {"statement": "Urteil: mit bloßem Auge nein", "sheet": "BLATT 02",
                         "rows": [["Mond", "nicht sichtbar"], ["Umlaufbahn", "bloßes Auge: kaum"], ["Kamera", "mit Teleobjektiv: ja"], ["Quelle", "NASA"]],
                         "cta": {"text": "Folge Gigastruct", "at": "@Folge"}}},
         "en": {"spoken": "So: it can be photographed, but not seen with the naked eye. China's first astronaut, Yang Liwei, said he did not see the wall. So it is not invisible from space, but you cannot simply look down and spot it either. Follow Gigastruct for the next check.",
                "data": {"statement": "Verdict: not with the naked eye", "sheet": "SHEET 02",
                         "rows": [["Moon", "not visible"], ["Orbit", "naked eye: barely"], ["Camera", "telephoto: yes"], ["Source", "NASA"]],
                         "cta": {"text": "Follow Gigastruct", "at": "@Follow"}}}},
    ],
}

